def recur(start: str, rule: str, count: int) -> list[str]:
    from datetime import date, timedelta
    from calendar import monthrange

    start_date = date.fromisoformat(start)
    parts = rule.split()
    frequency = parts[0]
    step = int(parts[1])
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                "FR": 4, "SA": 5, "SU": 6}
    result = []

    if frequency == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * step)).isoformat())

    elif frequency == "WEEKLY":
        days = sorted(weekdays[day] for day in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week = 0
        while len(result) < count:
            for day in days:
                candidate = week_start + timedelta(weeks=week, days=day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        break
            week += step

    elif frequency == "MONTHLY":
        initial_month = start_date.year * 12 + start_date.month - 1
        month_offset = 0

        while len(result) < count:
            year, month_index = divmod(initial_month + month_offset, 12)
            month = month_index + 1
            first_weekday, last_day = monthrange(year, month)

            if len(parts) == 3:
                day = int(parts[2])
                if day == -1:
                    day = last_day
            else:
                nth = int(parts[2])
                weekday = weekdays[parts[3]]
                if nth == -1:
                    last_weekday = (first_weekday + last_day - 1) % 7
                    day = last_day - (last_weekday - weekday) % 7
                else:
                    day = 1 + (weekday - first_weekday) % 7 + 7 * (nth - 1)

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())

            month_offset += step

    else:
        month, day = map(int, parts[2].split("-"))
        year = start_date.year

        while len(result) < count:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
            year += step

    return result
